Definition w4s34_EcA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x12 x13 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S4 L4 PTR PN U BITS : Z) (w248 w256 : word),
    PTR = PN + U ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S4 ->
    S4 + L4 <= SS + n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rw_cells asegs mm (P + 248) [C4 w248] ->
    rw_cells asegs mm (P + 256) [C8 w256] ->
    rng RNG P 496 ->
