       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B')] ->
       rw_cells asegs mm' (P + 256) [C8 (Z_to_bv 64 PN)] ->
       B' = BITS - 8 * U ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 y11 x12 x13 (Z_to_bv 64 PN) y15 x16 (Z_to_bv 64
